def downsample_bucket(samples_10s):
    # Store associative aggregates (min, max, sum, count), never raw avg!
    if not samples_10s:
        return None
    return {
        'min': min(samples_10s),
        'max': max(samples_10s),
        'sum': sum(samples_10s),
        'count': len(samples_10s),
    }

def admit_series(tenant_id, series_hash, active_hll, quota_limit):
    if active_hll.estimate(tenant_id) >= quota_limit and not active_hll.seen(series_hash):
        raise CardinalityLimitError('429: Active series quota exceeded')
    active_hll.add(tenant_id, series_hash)
